<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use CetechDeliveryEngine\Domain\CustomerPolicy\{PolicyFamilyRecord,PolicyJson,PolicyLineage,PolicyLinePacket,PolicyOrderManifest};
use CetechDeliveryEngine\Domain\RuleLifecycle\RuleTime;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyDomainFixture as F;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
final class DomainPolicyPacketTest extends TestCase {
    public function test_original_packet_retains_exact_native_coordinates_and_both_closed_families():void{$p=F::packet();self::assertSame(456,$p->lineage()->facts()['item_id']);self::assertSame(123,$p->lineage()->facts()['order_id']);self::assertSame('1',$p->lineage()->facts()['quantity']);self::assertSame(PolicyFamilyRecord::FAMILIES,array_keys($p->families()));self::assertSame($p->digest(),PolicyLinePacket::from_private_json($p->private_json())->digest());self::assertSame(F::NOW,$p->captured_at()->sql());self::assertStringContainsString('PRIVATE supplied policy',$p->private_json());self::assertNotSame($p->digest(),$p->lineage()->digest());}
    public function test_variation_packet_pins_the_actual_native_parent_without_product_fallback():void{$p=F::packet(variation:true);self::assertSame(44,$p->lineage()->facts()['variation_id']);self::assertSame(33,$p->lineage()->facts()['parent_id']);$this->refused(static fn()=>F::packet(['variation_id'=>44,'parent_id'=>33]));$this->refused(static fn()=>F::packet(['variation_id'=>44,'parent_id'=>34],true));}
    #[DataProvider('bad_lineage')]
    public function test_lineage_uses_closed_typed_bounded_native_identities(string$key,mixed$value):void{$this->refused(static fn()=>F::lineage([$key=>$value]));}
    public static function bad_lineage():array{return[
        ['format',2],['site_id',0],['site_id','1'],['order_id',0],['order_id',1.0],['item_id',false],['product_id',0],['variation_id',-1],['variation_id',33],['parent_id',33],['quantity',1],['quantity','01'],['quantity','1.5'],['quantity','0'],['quantity','9223372036854775808'],['real_offer_id',0],['real_offer_id',null],['owner_uuid','f'],['line_uuid','00000000-0000-0000-0000-000000000001'],['owner_digest',str_repeat('A',64)],['cart_line_digest','native-key'],['customer_context_digest',''],['raw_package_digest',null],['raw_line_digest',str_repeat('a',63)],['presentation_material_digest',str_repeat('a',65)],['unknown',1]];}
    public function test_cart_key_has_exact_utf8_bound_and_site_domain():void{$key=str_repeat('x',PolicyLineage::MAX_CART_KEY_BYTES);self::assertMatchesRegularExpression('/^[0-9a-f]{64}$/D',PolicyLineage::cart_line_digest(1,$key));self::assertNotSame(PolicyLineage::cart_line_digest(1,$key),PolicyLineage::cart_line_digest(2,$key));foreach(['',$key.'x',"\xff"]as$bad){$this->refused(static fn()=>PolicyLineage::cart_line_digest(1,$bad));}}
    public function test_reservation_is_at_least_every_actual_maximum_width_packet_and_does_not_mutate_content():void{$f=F::families();$reserved=PolicyLinePacket::reserved_bytes($f['return_policy_v1'],$f['refund_policy_v1']);$p=F::packet();self::assertGreaterThanOrEqual(strlen($p->private_json()),$reserved);self::assertLessThanOrEqual(PolicyLinePacket::MAX_BYTES,$reserved);self::assertSame($f['return_policy_v1']->digest(),$p->families()['return_policy_v1']->digest());}
    public function test_wrong_family_offer_coordinate_and_capture_time_refuse():void{$f=F::families();$at=RuleTime::parse(F::NOW);foreach([static fn()=>PolicyLinePacket::freeze(F::lineage(),$f['refund_policy_v1'],$f['return_policy_v1'],$at),static fn()=>PolicyLinePacket::freeze(F::lineage(['real_offer_id'=>5]),$f['return_policy_v1'],$f['refund_policy_v1'],$at),static fn()=>PolicyLinePacket::freeze(F::lineage(['product_id'=>34]),$f['return_policy_v1'],$f['refund_policy_v1'],$at),static fn()=>PolicyLinePacket::freeze(F::lineage(),$f['return_policy_v1'],$f['refund_policy_v1'],RuleTime::parse('2026-10-24 12:00:01.000000'))]as$make){$this->refused($make);}}
    public function test_saved_packet_rejects_future_missing_and_modified_payloads():void{$p=F::packet();$f=$p->facts();foreach(['format','lineage','captured_at','families']as$key){$bad=$f;unset($bad[$key]);$this->refused(static fn()=>PolicyLinePacket::from_private_json(PolicyJson::encode($bad)));}$f['format']=2;$this->refused(static fn()=>PolicyLinePacket::from_private_json(PolicyJson::encode($f)));$f=$p->facts();$f['families']->return_policy_v1->content->full_text='overwritten';$this->refused(static fn()=>PolicyLinePacket::from_private_json(PolicyJson::encode($f)));$f=$p->facts();$f['lineage']->real_offer_id=9;$this->refused(static fn()=>PolicyLinePacket::from_private_json(PolicyJson::encode($f)));$this->refused(static fn()=>PolicyLinePacket::from_private_json(' '.$p->private_json()));}
    public function test_order_manifest_sorts_exact_item_census_and_exposes_only_private_detached_entries():void{$a=F::packet();$b=F::packet(['item_id'=>455,'line_uuid'=>F::uuid(702)]);$m=PolicyOrderManifest::from_lines(1,123,F::uuid(700),[$a,$b],RuleTime::parse(F::NOW));self::assertSame([455,456],array_column($m->entries(),'item_id'));self::assertSame($b->digest(),$m->entries()[0]['packet_digest']);self::assertSame(F::uuid(700),$m->facts()['owner_uuid']);self::assertSame(str_repeat('a',64),$m->facts()['owner_digest']);self::assertSame($m->private_json(),PolicyOrderManifest::from_private_json($m->private_json())->private_json());self::assertLessThanOrEqual(PolicyOrderManifest::MAX_BYTES,strlen($m->private_json()));$f=$m->facts();$f['entries'][0]->packet_digest=str_repeat('b',64);self::assertSame($b->digest(),$m->entries()[0]['packet_digest']);}
    public function test_two_hundred_real_packets_fit_and_two_hundred_one_refuses_before_manifest():void{$f=F::families();$p=[];$at=RuleTime::parse(F::NOW);for($i=1;$i<=200;++$i){$p[]=PolicyLinePacket::freeze(F::lineage(['item_id'=>1000+$i,'line_uuid'=>F::uuid(1000+$i)]),$f['return_policy_v1'],$f['refund_policy_v1'],$at);}self::assertCount(200,PolicyOrderManifest::from_lines(1,123,F::uuid(700),$p,$at)->entries());$p[]=F::packet();$this->refused(static fn()=>PolicyOrderManifest::from_lines(1,123,F::uuid(700),$p,$at));}
    public function test_genuine_large_authored_packets_reach_aggregate_budget_before_line_census_ceiling():void{$r=F::capture(content:['full_text'=>str_repeat('r',14000)])['record'];$f=F::capture('refund_policy_v1',content:['full_text'=>str_repeat('f',14000)])['record'];$at=RuleTime::parse(F::NOW);$base=PolicyLinePacket::freeze(F::lineage(),$r,$f,$at);$n=intdiv(PolicyLinePacket::MAX_AGGREGATE_BYTES,strlen($base->private_json()));self::assertLessThan(200,$n);$packets=[];for($i=0;$i<=$n;++$i){$packets[]=PolicyLinePacket::freeze(F::lineage(['item_id'=>1000+$i,'line_uuid'=>F::uuid(1000+$i)]),$r,$f,$at);}self::assertCount($n,PolicyOrderManifest::from_lines(1,123,F::uuid(700),array_slice($packets,0,$n),$at)->entries());$this->refused(static fn()=>PolicyOrderManifest::from_lines(1,123,F::uuid(700),$packets,$at));}
    #[DataProvider('manifest_mismatch')]
    public function test_manifest_rejects_other_order_owner_site_or_duplicate_line_census(string$kind):void{$a=F::packet();$b=match($kind){'order'=>F::packet(['order_id'=>124,'item_id'=>457,'line_uuid'=>F::uuid(702)]),'owner'=>F::packet(['owner_uuid'=>F::uuid(703),'item_id'=>457,'line_uuid'=>F::uuid(702)]),'owner digest'=>F::packet(['owner_digest'=>str_repeat('b',64),'item_id'=>457,'line_uuid'=>F::uuid(702)]),'same item'=>F::packet(['line_uuid'=>F::uuid(702)]),'same uuid'=>F::packet(['item_id'=>457]),default=>$a};$this->refused(static fn()=>PolicyOrderManifest::from_lines('site'===$kind?2:1,123,F::uuid(700),[$a,$b],RuleTime::parse(F::NOW)));}
    public static function manifest_mismatch():array{return array_map(static fn($x)=>[$x],['site','order','owner','owner digest','same item','same uuid']);}
    public function test_manifest_missing_future_null_duplicate_and_unsorted_entries_refuse():void{$m=PolicyOrderManifest::from_lines(1,123,F::uuid(700),[F::packet(),F::packet(['item_id'=>457,'line_uuid'=>F::uuid(702)])],RuleTime::parse(F::NOW));foreach(['format','site_id','order_id','owner_uuid','owner_digest','captured_at','entries']as$key){$f=$m->facts();unset($f[$key]);$this->refused(static fn()=>PolicyOrderManifest::from_private_json(PolicyJson::encode($f)));}$f=$m->facts();$f['format']=2;$this->refused(static fn()=>PolicyOrderManifest::from_private_json(PolicyJson::encode($f)));$f=$m->facts();$f['entries'][0]->packet_digest=null;$this->refused(static fn()=>PolicyOrderManifest::from_private_json(PolicyJson::encode($f)));$f=$m->facts();$f['entries']=array_reverse($f['entries']);$this->refused(static fn()=>PolicyOrderManifest::from_private_json(PolicyJson::encode($f)));$f=$m->facts();$f['entries'][]=$f['entries'][0];$this->refused(static fn()=>PolicyOrderManifest::from_private_json(PolicyJson::encode($f)));}
    public function test_all_history_values_refuse_implicit_serialization_and_debug_body_leak():void{$p=F::packet();$m=PolicyOrderManifest::from_lines(1,123,F::uuid(700),[$p],RuleTime::parse(F::NOW));foreach([$p,$p->lineage(),$m]as$v){foreach([static fn()=>json_encode($v,JSON_THROW_ON_ERROR),static fn()=>serialize($v)]as$make){try{$make();self::fail('Implicit serialization allowed');}catch(\LogicException){self::assertTrue(true);}}ob_start();var_dump($v);$debug=ob_get_clean();self::assertStringNotContainsString('PRIVATE',$debug);self::assertStringNotContainsString('456',$debug);}}
    private function refused(callable$make):void{$refused=false;try{$make();}catch(\InvalidArgumentException){$refused=true;}self::assertTrue($refused,'Invalid packet or manifest was accepted.');}
}
